-- paperclip:migration-safety-ignore large-create-index-not-concurrently: The migration runner wraps each migration in a transaction, so CONCURRENTLY is unavailable. This narrow partial index covers only wakes parked as deferred_issue_execution, a few rows of a large table, and it is additive: an image that predates it ignores it. Building it scans agent_wakeup_requests once and blocks writes to that table for the duration of the scan.
CREATE INDEX "agent_wakeup_requests_deferred_requested_idx" ON "agent_wakeup_requests" USING btree ("requested_at") WHERE "agent_wakeup_requests"."status" = 'deferred_issue_execution';
